// Definition of a MaintenanceWindow
type MaintenanceWindow struct {
	// Duration: Duration of the maintenance window in HH:mm format. If not provided, default value will be used based on
	// maintenance scope provided. Example: 05:00.
	Duration *string `json:"duration,omitempty"`

	// ExpirationDateTime: Effective expiration date of the maintenance window in YYYY-MM-DD hh:mm format. The window will be
	// created in the time zone provided and adjusted to daylight savings according to that time zone. Expiration date must be
	// set to a future date. If not provided, it will be set to the maximum datetime 9999-12-31 23:59:59.
	ExpirationDateTime *string `json:"expirationDateTime,omitempty"`

	// RecurEvery: Rate at which a Maintenance window is expected to recur. The rate can be expressed as daily, weekly, or
	// monthly schedules. Daily schedule are formatted as recurEvery: [Frequency as integer]['Day(s)']. If no frequency is
	// provided, the default frequency is 1. Daily schedule examples are recurEvery: Day, recurEvery: 3Days.  Weekly schedule
	// are formatted as recurEvery: [Frequency as integer]['Week(s)'] [Optional comma separated list of weekdays
	// Monday-Sunday]. Weekly schedule examples are recurEvery: 3Weeks, recurEvery: Week Saturday,Sunday. Monthly schedules are
	// formatted as [Frequency as integer]['Month(s)'] [Comma separated list of month days] or [Frequency as
	// integer]['Month(s)'] [Week of Month (First, Second, Third, Fourth, Last)] [Weekday Monday-Sunday] [Optional Offset(No.
	// of days)]. Offset value must be between -6 to 6 inclusive. Monthly schedule examples are recurEvery: Month, recurEvery:
	// 2Months, recurEvery: Month day23,day24, recurEvery: Month Last Sunday, recurEvery: Month Fourth Monday, recurEvery:
	// Month Last Sunday Offset-3, recurEvery: Month Third Sunday Offset6.
	RecurEvery *string `json:"recurEvery,omitempty"`

	// StartDateTime: Effective start date of the maintenance window in YYYY-MM-DD hh:mm format. The start date can be set to
	// either the current date or future date. The window will be created in the time zone provided and adjusted to daylight
	// savings according to that time zone.
	StartDateTime *string `json:"startDateTime,omitempty"`

	// TimeZone: Name of the timezone. List of timezones can be obtained by executing
	// [System.TimeZoneInfo]::GetSystemTimeZones() in PowerShell. Example: Pacific Standard Time, UTC, W. Europe Standard Time,
	// Korea Standard Time, Cen. Australia Standard Time.
	TimeZone *string `json:"timeZone,omitempty"`
}

